import {useEffect,useMemo,useState,type FormEvent} from 'react';
import {Home as HomeIcon,Heart,Search,UserRound,BookOpen,ChevronRight,ChevronLeft,Clock3,Plus,Download,Upload,Trash2,Bell,Share2,CalendarDays,Check,Star,ShieldCheck,ExternalLink,Lightbulb,Menu,Settings2} from 'lucide-react';
import {activities,skills,sources,mappings,riskRules,sourceMap,skillMap,contentVersion,mode,productionReady,eligibleActivities} from './content';
import {buildActivityPlan} from './activity-plan';
import {ageLabel,childAge,today,gestation,daysBetween} from './age';
